@Appender(_shared_docs["pct_change"] % _shared_doc_kwargs)
def pct_change(self, periods=1, fill_method="pad", limit=None, freq=None, **kwargs):
    axis = self._get_axis_number(kwargs.pop("axis", self._stat_axis_name))
    if fill_method is None:
        data = self
    else:
        data = self.fillna(method=fill_method, limit=limit, axis=axis)

    shifted_data = data.shift(periods=periods, freq=freq, axis=axis, **kwargs)

    # Handle case for duplicate indices by using groupby to calculate pct_change
    if not shifted_data.index.is_unique:
        return data.groupby(level=0).apply(lambda x: x.pct_change(periods=periods, fill_method=fill_method, limit=limit, axis=axis))

